import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { SecureStorageService } from '../storage/secure-storage.service';
import { ValidateResponse, setUserInfo } from '../../interfaces/login.interface';

export interface ValidationResult {
  isValid: boolean;
  userDetail: setUserInfo | null;
}

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

@Injectable({
  providedIn: 'root'
})
export class AuthValidationService {

  private cachedResult: ValidationResult | null = null;
  private cacheTimestamp = 0;
  private pendingValidation: Promise<ValidationResult> | null = null;

  constructor(
    private http: HttpClient,
    private secureStorage: SecureStorageService
  ) {}

  async validate(): Promise<ValidationResult> {
    // Check for forced logout flag (set by SocketService on login from another browser)
    if (localStorage.getItem('force_logout')) {
      console.warn('AuthValidationService: Force logout detected. Invalidating session.');
      localStorage.removeItem('force_logout');
      this.clearCache();
      return { isValid: false, userDetail: null };
    }

    const cookieLogin = await this.secureStorage.checkLogin();
    let userDetail: setUserInfo | null = null;
    if (cookieLogin) {
      userDetail = await this.secureStorage.getUserInfo();
    }

    return {
      isValid: cookieLogin,
      userDetail
    };
  }

  clearCache(): void {
    this.cachedResult = null;
    this.cacheTimestamp = 0;
    this.pendingValidation = null;
  }
}
